27	/// The fewest lines a class or object member needs to get a block of its own. A shorter one is a stub or accessor that
28	/// the block holding it already shows whole.
29	const MIN_MEMBER_LINES: usize = 3;
30	
31	/// Stack reserved per byte of source. A stack overflow aborts the process, so the stack must be big enough before the
32	/// parse starts. Each level of the parser's or the extractor's recursion consumes at least one byte, and the costliest
33	/// level measured, a `[` in a type, uses 1.7 KB of stack optimized and 4.6 KB unoptimized: this is over twice that.
34	///
35	/// `debug_assertions` stands in for "unoptimized", which `cfg!` cannot ask for directly. A release profile with debug
36	/// assertions pays the larger budget and the smaller length cap for nothing; a profile that disables optimizations
37	/// without them gets the smaller budget and could overflow. Change the constant if the workspace adds such a profile.
38	const STACK_PER_SOURCE_BYTE: usize = if cfg!(debug_assertions) { 12 << 10 } else { 4 << 10 };
39	
40	/// Stack for what does not grow with the source.
41	const BASE_STACK: usize = 8 << 20;
42	
43	/// The most stack one parse reserves. Only touched pages are committed, but a hostile file of the longest parsed length
44	/// can touch about half of it (460 MiB measured), so this also bounds a parse's memory.
45	const MAX_STACK: usize = 1 << 30;
46	
47	/// The longest source that is parsed; a longer one could need more than [`MAX_STACK`].
48	pub(super) const MAX_PARSED_SOURCE_LEN: usize = (MAX_STACK - BASE_STACK) / STACK_PER_SOURCE_BYTE;
49	
50	/// Everything extracted from one file, before it is wrapped in a `FileAnalysis`.
51	#[derive(Debug, Default)]
52	pub(super) struct Extraction {
53	    pub(super) symbols: Vec<SymbolEntry>,
54	    pub(super) dependencies: Vec<DependencyRecord>,
55	    pub(super) exports: Vec<ExportRecord>,
56	    pub(super) blocks: Vec<CodeBlock>,
57	    pub(super) jsx_elements: Vec<JsxElementEntry>,
58	    pub(super) type_only_imports: Vec<String>,
59	    pub(super) had_parse_errors: bool,
60	    pub(super) degradation: Option<Degradation>,
61	}
62	
63	impl Extraction {
64	    /// The result for a file that could not be analyzed: no data, flagged as having errors and the reason.
65	    fn degraded(degradation: Degradation) -> Self {
66	        Self { had_parse_errors: true, degradation: Some(degradation), ..Self::default() }
67	    }
68	}
69	
70	/// Extracts what `profile` asks for from `source`.
71	///
72	/// A file too long to be sure of its stack, or one whose parse or extraction panics, yields [`Extraction::degraded`]
73	/// with the reason.
74	pub(super) fn extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
75	    if source.len() > MAX_PARSED_SOURCE_LEN {
76	        return Extraction::degraded(Degradation::TooLarge { bytes: source.len(), cap: MAX_PARSED_SOURCE_LEN });
77	    }
78	    let stack_size = BASE_STACK + source.len() * STACK_PER_SOURCE_BYTE;
79	    guarded(stack_size, || parse_and_extract(path, source, profile))
80	}
81	
82	/// Runs `run` on its own thread with `stack_size` bytes of stack. A panic, or a thread that cannot be started, yields
83	/// [`Extraction::degraded`] with the reason.
84	fn guarded(stack_size: usize, run: impl FnOnce() -> Extraction + Send) -> Extraction {
85	    thread::scope(|scope| {
86	        let builder = thread::Builder::new().name("monokl-parse".to_owned()).stack_size(stack_size);
87	        let Ok(handle) = builder.spawn_scoped(scope, run) else {
88	            return Extraction::degraded(Degradation::ThreadUnavailable);
89	        };
90	        // The closure's output is discarded on a panic, so no torn state is observable afterwards.
91	        handle.join().unwrap_or_else(|_| Extraction::degraded(Degradation::Panicked))
92	    })
93	}
94	
95	/// JavaScript files may hold JSX whatever their extension; TypeScript files only in `.tsx`, since `<T>x` is a cast
96	/// elsewhere.
97	fn source_type_for(path: &Utf8Path) -> SourceType {
98	    let source_type = SourceType::from_path(path.as_std_path()).unwrap_or_else(|_| SourceType::ts());
99	    if source_type.is_javascript() { source_type.with_jsx(true) } else { source_type }
100	}
101	
102	fn parse_and_extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
103	    let allocator = Allocator::default();
104	    // Parentheses carry no meaning here and a `ParenthesizedExpression` node would only add a level to every walk.
105	    let options = ParseOptions { preserve_parens: false, ..ParseOptions::default() };
106	    let parsed = Parser::new(&allocator, source, source_type_for(path)).with_options(options).parse();
107	    // The recovered program is still used below, so record the diagnostics rather than discarding the parse.
108	    let had_parse_errors = parsed.fatal_error || !parsed.diagnostics.is_empty();
109	
110	    let mut extractor = Extractor { path, source, profile, lines: LineIndex::new(source), out: Extraction::default() };
111	    for statement in &parsed.program.body {
112	        extractor.statement(statement);
113	    }
114	    if profile == AnalysisProfile::Full {
115	        extractor.jsx(&parsed.program);
116	    }
117	    Extraction { had_parse_errors, ..extractor.out }
118	}
119	
120	/// Maps byte offsets to 1-based line numbers.
121	struct LineIndex {
122	    newlines: Vec<usize>,
123	}
124	
125	impl LineIndex {
126	    fn new(source: &str) -> Self {
127	        Self { newlines: source.bytes().enumerate().filter(|&(_, byte)| byte == b'\n').map(|(i, _)| i).collect() }
128	    }
129	
130	    fn line(&self, offset: u32) -> usize {
131	        self.newlines.partition_point(|&newline| newline < offset as usize) + 1
132	    }
133	}
134	
135	struct Extractor<'s> {
136	    path: &'s Utf8Path,
137	    source: &'s str,
138	    profile: AnalysisProfile,
139	    lines: LineIndex,
140	    out: Extraction,
141	}
142	
143	impl Extractor<'_> {
144	    fn structural(&self) -> bool {
145	        self.profile != AnalysisProfile::Dependencies
146	    }
147	
148	    fn text(&self, span: Span) -> &str {
149	        self.source.get(span.start as usize..span.end as usize).unwrap_or_default()
150	    }
151	
152	    fn statement(&mut self, statement: &Statement<'_>) {
153	        match statement {
154	            Statement::ImportDeclaration(decl) => self.import(decl),
155	            Statement::ExportDeclaration(decl) => self.export_declaration(decl),
156	            Statement::ExportNamedDeclaration(decl) => self.export_named(decl),
157	            Statement::ExportFromDeclaration(decl) => self.export_from(decl),
158	            Statement::ExportDefaultDeclaration(decl) => self.export_default(decl),
159	            Statement::ExportAllDeclaration(decl) => self.export_all(decl),
160	            Statement::FunctionDeclaration(function) => {
161	                self.function(function);
162	            }
163	            Statement::ClassDeclaration(class) => {
164	                self.class(class);
165	            }
166	            Statement::TSInterfaceDeclaration(decl) => {
167	                self.symbol(decl.id.name.as_str(), SymbolKind::Interface, decl.span, None);
168	            }
169	            Statement::TSTypeAliasDeclaration(decl) => {
170	                self.symbol(decl.id.name.as_str(), SymbolKind::TypeAlias, decl.span, None);
171	            }
172	            Statement::TSEnumDeclaration(decl) => {
173	                self.symbol(decl.id.name.as_str(), SymbolKind::Enum, decl.span, None);
174	            }
175	            Statement::VariableDeclaration(decl) => {
176	                self.variables(decl);
177	            }
178	            _ => {}
179	        }
180	        if self.profile == AnalysisProfile::Full {
181	            self.block(statement);
182	            self.member_blocks(statement);
183	        }
184	    }
185	
186	    fn symbol(&mut self, name: &str, kind: SymbolKind, span: Span, signature: Option<String>) {
187	        if !self.structural() {
188	            return;
189	        }
190	        self.out.symbols.push(SymbolEntry {
191	            name: name.to_owned(),
192	            kind,
193	            line: self.lines.line(span.start),
194	            signature,
195	            owner: None,
196	            trait_impl: None,
197	            visibility: None,
198	            kind_detail: None,
199	        });
200	    }
201	
202	    fn export(&mut self, name: String, span: Span, re_export: bool) {
203	        if !self.structural() {
204	            return;
205	        }
206	        self.out.exports.push(ExportRecord { name, line: self.lines.line(span.start), re_export });
207	    }
208	
209	    /// Records a function symbol and returns its name; anonymous functions have none.
210	    fn function(&mut self, function: &Function<'_>) -> Option<String> {
211	        let name = function.id.as_ref()?.name.as_str();
212	        let signature = self.function_signature(function);
213	        self.symbol(name, SymbolKind::Function, function.span, Some(signature));
214	        Some(name.to_owned())
215	    }
216	
217	    /// The function's text up to its body, on one line: `function f(a: A): B`.
218	    fn function_signature(&self, function: &Function<'_>) -> String {
219	        let end = function.body.as_ref().map_or(function.span.end, |body| body.span.start);
220	        self.signature_text(Span::new(function.span.start, end))
221	    }
222	
223	    /// The text of `span` on one line, without a trailing `;`.
224	    fn signature_text(&self, span: Span) -> String {
225	        self.text(span).split_whitespace().collect::<Vec<_>>().join(" ").trim_end_matches(';').trim_end().to_owned()
226	    }
227	
228	    fn class(&mut self, class: &Class<'_>) -> Option<String> {
229	        let name = class.id.as_ref()?.name.as_str();
230	        self.symbol(name, SymbolKind::Class, class.span, None);
231	        Some(name.to_owned())
232	    }
233	
234	    fn variables(&mut self, decl: &VariableDeclaration<'_>) -> Vec<String> {
235	        let mut names = Vec::new();
236	        for declarator in &decl.declarations {
237	            if let BindingPattern::BindingIdentifier(id) = &declarator.id {
238	                self.symbol(id.name.as_str(), SymbolKind::Variable, declarator.span, None);
239	                names.push(id.name.as_str().to_owned());
240	            }
241	        }
242	        names
243	    }
244	
245	    /// Records the symbols a declaration introduces and returns their names.
246	    fn declaration(&mut self, decl: &Declaration<'_>) -> Vec<String> {
247	        match decl {
248	            Declaration::FunctionDeclaration(function) => self.function(function).into_iter().collect(),
249	            Declaration::ClassDeclaration(class) => self.class(class).into_iter().collect(),
250	            Declaration::TSInterfaceDeclaration(decl) => {
251	                self.symbol(decl.id.name.as_str(), SymbolKind::Interface, decl.span, None);
252	                vec![decl.id.name.as_str().to_owned()]
253	            }
254	            Declaration::TSTypeAliasDeclaration(decl) => {
255	                self.symbol(decl.id.name.as_str(), SymbolKind::TypeAlias, decl.span, None);
256	                vec![decl.id.name.as_str().to_owned()]
257	            }
258	            Declaration::TSEnumDeclaration(decl) => {
259	                self.symbol(decl.id.name.as_str(), SymbolKind::Enum, decl.span, None);
260	                vec![decl.id.name.as_str().to_owned()]
261	            }
262	            Declaration::VariableDeclaration(decl) => self.variables(decl),
263	            Declaration::TSExternalModuleDeclaration(_)
264	            | Declaration::TSNamespaceDeclaration(_)
265	            | Declaration::TSGlobalDeclaration(_)
266	            | Declaration::TSImportEqualsDeclaration(_) => Vec::new(),
267	        }
268	    }
269	
270	    fn import(&mut self, decl: &ImportDeclaration<'_>) {
271	        let specifier = decl.source.value.as_str().to_owned();
272	        if decl.import_kind.is_type() {
273	            self.out.type_only_imports.push(specifier);
274	            return;
275	        }
276	        let mut bindings = Vec::new();
277	        for specifier in decl.specifiers.iter().flatten() {
278	            match specifier {
279	                ImportDeclarationSpecifier::ImportSpecifier(named) => {
280	                    if !named.import_kind.is_type() {
281	                        bindings.push(DependencyBinding {
282	                            imported: module_export_name(&named.imported),
283	                            local: named.local.name.as_str().to_owned(),
284	                            kind: BindingKind::Named,
285	                        });
286	                    }
287	                }
288	                ImportDeclarationSpecifier::ImportDefaultSpecifier(default) => bindings.push(DependencyBinding {
289	                    imported: "default".to_owned(),
290	                    local: default.local.name.as_str().to_owned(),
291	                    kind: BindingKind::Default,
292	                }),
293	                ImportDeclarationSpecifier::ImportNamespaceSpecifier(namespace) => bindings.push(DependencyBinding {
294	                    imported: "*".to_owned(),
295	                    local: namespace.local.name.as_str().to_owned(),
296	                    kind: BindingKind::Namespace,
297	                }),
298	            }
299	        }
300	        self.dependency(decl.source.value.as_str(), decl.span, bindings);
301	    }
302	
303	    fn dependency(&mut self, specifier: &str, span: Span, bindings: Vec<DependencyBinding>) {
304	        self.out.dependencies.push(DependencyRecord {
305	            line: self.lines.line(span.start),
306	            bindings,
307	            target: DependencyTarget::File {
308	                specifier: specifier.to_owned(),
309	                resolved: None,
310	                is_relative: specifier.starts_with('.'),
311	            },
312	        });
313	    }
314	
315	    /// `export function f() {}`, `export const x = 1`.
316	    fn export_declaration(&mut self, decl: &ExportDeclaration<'_>) {
317	        for name in self.declaration(&decl.declaration) {
318	            self.export(name, decl.span, false);
319	        }
320	    }
321	
322	    /// `export { a, b as c }`.
323	    fn export_named(&mut self, decl: &ExportNamedDeclaration<'_>) {
324	        for specifier in &decl.specifiers {
325	            self.export(module_export_name(&specifier.exported), decl.span, false);
326	        }
327	    }
