5	use std::thread;
6	
7	use camino::Utf8Path;
8	use oxc_allocator::Allocator;
9	use oxc_ast::ast::{
10	    BindingPattern, Class, ClassElement, Declaration, ExportAllDeclaration, ExportDeclaration,
11	    ExportDefaultDeclaration, ExportDefaultDeclarationKind, ExportFromDeclaration, ExportNamedDeclaration, Expression,
12	    Function, ImportDeclaration, ImportDeclarationSpecifier, JSXAttributeItem, JSXAttributeName, JSXAttributeValue,
13	    JSXElement, JSXElementName, JSXMemberExpression, JSXMemberExpressionObject, MethodDefinition, MethodDefinitionKind,
14	    ModuleExportName, ObjectExpression, ObjectProperty, ObjectPropertyKind, Program, PropertyDefinition, PropertyKind,
