14	/// The fewest lines an `impl` or trait method needs to get a block of its own. A shorter one is a stub or accessor
15	/// that the block holding it already shows whole.
16	const MIN_MEMBER_LINES: usize = 3;
17	
18	/// Stack reserved per byte of source. A stack overflow aborts the process, so the stack must be big enough before the
19	/// parse starts. Each level of the parser's recursion consumes at least one byte of source, and the costliest level
20	/// measured (a nested `(`, `{` or unary `-`) uses under 1.6 KB of stack optimized and under 4 KB unoptimized.
21	///
22	/// The parser's time grows with the square of the nesting depth (20,000 nested parentheses take a second), so a file of
23	/// the longest parsed length made only of them takes minutes. Only a pathological file reaches that.
24	///
25	/// `debug_assertions` stands in for "unoptimized", which `cfg!` cannot ask for directly.
26	const STACK_PER_SOURCE_BYTE: usize = if cfg!(debug_assertions) { 12 << 10 } else { 4 << 10 };
27	
28	/// Stack for what does not grow with the source.
29	const BASE_STACK: usize = 8 << 20;
30	
31	/// The most stack one parse reserves. Only touched pages are committed; a parse whose stack cannot be reserved is
32	/// reported as degraded.
33	const MAX_STACK: usize = 4 << 30;
34	
35	/// The longest source that is parsed; a longer one could need more than [`MAX_STACK`].
36	pub(super) const MAX_PARSED_SOURCE_LEN: usize = (MAX_STACK - BASE_STACK) / STACK_PER_SOURCE_BYTE;
37	
38	/// The deepest syntax tree that is kept. `ra_ap_syntax` hands a finished tree to a shared background thread to drop, one
39	/// with the default 2 MiB stack, and a drop recurses once per level of the tree: about 350 bytes a level unoptimized
40	/// and 130 optimized. Overflowing that stack aborts the process, so this stays at half of what fits.
41	pub(super) const MAX_TREE_DEPTH: usize = if cfg!(debug_assertions) { 2_000 } else { 8_000 };
42	
43	/// Everything extracted from one file, before it is wrapped in a `FileAnalysis`.
44	#[derive(Debug, Default)]
45	pub(super) struct Extraction {
46	    pub(super) symbols: Vec<SymbolEntry>,
47	    pub(super) blocks: Vec<CodeBlock>,
48	    pub(super) test_blocks: Vec<CodeBlock>,
49	    pub(super) had_parse_errors: bool,
50	    pub(super) degradation: Option<Degradation>,
51	}
52	
53	impl Extraction {
54	    /// The result for a file that could not be analyzed: no data, flagged as having errors and the reason.
55	    fn degraded(degradation: Degradation) -> Self {
56	        Self { had_parse_errors: true, degradation: Some(degradation), ..Self::default() }
57	    }
58	}
59	
60	/// Extracts what `profile` asks for from `source`.
61	///
62	/// Rust files have no dependency records, so the dependencies profile reads nothing. A file too long to be sure of its
63	/// stack, or one whose parse or extraction panics, yields [`Extraction::degraded`] with the reason.
64	pub(super) fn extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
65	    if profile == AnalysisProfile::Dependencies {
66	        return Extraction::default();
67	    }
68	    if source.len() > MAX_PARSED_SOURCE_LEN {
69	        return Extraction::degraded(Degradation::TooLarge { bytes: source.len(), cap: MAX_PARSED_SOURCE_LEN });
70	    }
71	    let stack_size = BASE_STACK + source.len() * STACK_PER_SOURCE_BYTE;
72	    guarded(stack_size, || parse_and_extract(path, source, profile))
73	}
74	
75	/// Runs `run` on its own thread with `stack_size` bytes of stack. A panic, or a thread that cannot be started, yields
76	/// [`Extraction::degraded`] with the reason.
77	fn guarded(stack_size: usize, run: impl FnOnce() -> Extraction + Send) -> Extraction {
78	    thread::scope(|scope| {
79	        let builder = thread::Builder::new().name("monokl-parse".to_owned()).stack_size(stack_size);
80	        let Ok(handle) = builder.spawn_scoped(scope, run) else {
81	            return Extraction::degraded(Degradation::ThreadUnavailable);
82	        };
83	        // The closure's output is discarded on a panic, so no torn state is observable afterwards.
84	        handle.join().unwrap_or_else(|_| Extraction::degraded(Degradation::Panicked))
85	    })
86	}
87	
88	fn parse_and_extract(path: &Utf8Path, source: &str, profile: AnalysisProfile) -> Extraction {
89	    let parse = SourceFile::parse(source, Edition::CURRENT);
90	    let depth = tree_depth(&parse.syntax_node());
91	    if depth > MAX_TREE_DEPTH {
92	        // The tree is leaked rather than dropped: its drop would run on the shared thread, where it would overflow.
93	        std::mem::forget(parse);
94	        return Extraction::degraded(Degradation::TooDeep { depth, cap: MAX_TREE_DEPTH });
95	    }
96	    let had_parse_errors = !parse.errors().is_empty();
97	    // The root of a parse is always a source file, so the cast cannot fail; the let-else keeps that out of a panic.
98	    let Some(file) = SourceFile::cast(parse.syntax_node()) else {
99	        return Extraction::degraded(Degradation::Panicked);
100	    };
101	    let mut walker = Walker { path, source, profile, lines: LineIndex::new(source), out: Extraction::default() };
102	    let file_is_test = file.attrs().any(|attr| attr.excl_token().is_some() && is_test_attr(&attr));
103	    walker.items(file.items(), None, file_is_test);
104	    Extraction { had_parse_errors, ..walker.out }
105	}
106	
107	/// The number of levels of `root`'s tree, the root being the first.
108	fn tree_depth(root: &SyntaxNode) -> usize {
109	    let (mut depth, mut deepest) = (0usize, 0usize);
110	    for event in root.preorder() {
111	        match event {
112	            WalkEvent::Enter(_) => {
113	                depth += 1;
114	                deepest = deepest.max(depth);
115	            }
116	            WalkEvent::Leave(_) => depth = depth.saturating_sub(1),
117	        }
118	    }
119	    deepest
120	}
121	
122	/// Maps byte offsets to 1-based line numbers.
123	struct LineIndex {
124	    newlines: Vec<u32>,
125	}
126	
127	impl LineIndex {
128	    fn new(source: &str) -> Self {
129	        Self {
130	            newlines: source
131	                .bytes()
132	                .enumerate()
133	                .filter(|&(_, byte)| byte == b'\n')
134	                .filter_map(|(offset, _)| u32::try_from(offset).ok())
135	                .collect(),
136	        }
137	    }
138	
139	    fn line(&self, offset: u32) -> usize {
140	        self.newlines.partition_point(|&newline| newline < offset) + 1
141	    }
142	}
143	
144	/// The item whose members are being walked: what each member block takes as its parent.
145	struct Holder {
146	    parent: ParentContext,
147	    /// The type that owns the members: an `impl`'s target or a trait's name; `None` for a module.
148	    owner: Option<String>,
149	    /// The trait an `impl` implements.
150	    trait_impl: Option<String>,
151	}
152	
153	/// An item or method as the walk found it.
154	struct Declared<'a> {
155	    node: &'a SyntaxNode,
156	    kind: SymbolKind,
157	    /// `None` for an item that has no name (a macro call, an `extern` block) or that the parse recovered without one.
158	    name: Option<&'a str>,
159	    visibility: Option<ast::Visibility>,
160	}
161	
162	struct Walker<'s> {
163	    path: &'s Utf8Path,
164	    source: &'s str,
165	    profile: AnalysisProfile,
166	    lines: LineIndex,
167	    out: Extraction,
168	}
169	
170	impl Walker<'_> {
171	    fn text(&self, range: TextRange) -> &str {
172	        self.source.get(usize::from(range.start())..usize::from(range.end())).unwrap_or_default()
173	    }
174	
175	    fn line_of(&self, offset: ra_ap_syntax::TextSize) -> usize {
176	        self.lines.line(u32::from(offset))
177	    }
178	
179	    /// Walks the items of a file or an inline module. Each becomes a block, then its own members do. `in_test` marks
180	    /// the items as test code when an enclosing item or file is.
181	    fn items(&mut self, items: impl Iterator<Item = ast::Item>, holder: Option<&Holder>, in_test: bool) {
182	        for item in items {
183	            self.item(&item, holder, in_test);
184	        }
185	    }
186	
187	    fn item(&mut self, item: &ast::Item, holder: Option<&Holder>, in_test: bool) {
188	        let Some((kind, name)) = describe(item) else { return };
189	        let in_test = in_test || item.attrs().any(|attr| is_test_attr(&attr));
190	        let declared = Declared { node: item.syntax(), kind, name: name.as_deref(), visibility: item_visibility(item) };
191	        self.record(&declared, holder, in_test);
192	
193	        let Some(name) = name else { return };
194	        let line = self.line_of(item.syntax().text_range().start());
195	        match item {
196	            ast::Item::Module(module) => {
197	                let Some(list) = module.item_list() else { return };
198	                let holder = Holder { parent: ParentContext { kind, name, line }, owner: None, trait_impl: None };
199	                self.items(list.items(), Some(&holder), in_test);
200	            }
201	            ast::Item::Impl(imp) => {
202	                let trait_impl = imp.trait_().map(|ty| collapse(&ty.syntax().text().to_string()));
203	                let owner = imp.self_ty().map(|ty| collapse(&ty.syntax().text().to_string()));
204	                let holder = Holder { parent: ParentContext { kind, name, line }, owner, trait_impl };
205	                self.methods(imp.assoc_item_list(), &holder, in_test);
206	            }
207	            ast::Item::Trait(item_trait) => {
208	                let holder =
209	                    Holder { owner: Some(name.clone()), parent: ParentContext { kind, name, line }, trait_impl: None };
210	                self.methods(item_trait.assoc_item_list(), &holder, in_test);
211	            }
212	            ast::Item::AsmExpr(_)
213	            | ast::Item::Const(_)
214	            | ast::Item::Enum(_)
215	            | ast::Item::ExternBlock(_)
216	            | ast::Item::ExternCrate(_)
217	            | ast::Item::Fn(_)
218	            | ast::Item::MacroCall(_)
219	            | ast::Item::MacroDef(_)
220	            | ast::Item::MacroRules(_)
221	            | ast::Item::Static(_)
222	            | ast::Item::Struct(_)
223	            | ast::Item::TypeAlias(_)
224	            | ast::Item::Union(_)
225	            | ast::Item::Use(_) => {}
226	        }
227	    }
228	
229	    /// A block for each method with a body in an `impl` or trait, at least [`MIN_MEMBER_LINES`] long unless it is test
230	    /// code. Any other member (a bodiless method, a constant, a type, a macro call) gets one only when it is itself
231	    /// marked as test code, so its matches do not go to the holder.
232	    fn methods(&mut self, list: Option<ast::AssocItemList>, holder: &Holder, in_test: bool) {
233	        let Some(list) = list else { return };
234	        for member in list.assoc_items() {
235	            let marked = member.attrs().any(|attr| is_test_attr(&attr));
236	            let (kind, name, visibility, node) = match &member {
237	                ast::AssocItem::Fn(function) if function.body().is_some() => {
238	                    let Some(name) = function.name() else { continue };
239	                    let in_test = in_test || marked;
240	                    let range = function.syntax().text_range();
241	                    // A short test method still gets a block, so a search can tell its matches from the holder's.
242	                    if !in_test && self.line_of(range.end()) - self.line_of(range.start()) + 1 < MIN_MEMBER_LINES {
243	                        continue;
244	                    }
245	                    let declared = Declared {
246	                        node: function.syntax(),
247	                        kind: SymbolKind::Method,
248	                        name: Some(name.text()),
249	                        visibility: function.visibility(),
250	                    };
251	                    self.record(&declared, Some(holder), in_test);
252	                    continue;
253	                }
254	                ast::AssocItem::Fn(function) => {
255	                    (SymbolKind::Method, function.name(), function.visibility(), function.syntax())
256	                }
257	                ast::AssocItem::Const(item) => (SymbolKind::Variable, item.name(), item.visibility(), item.syntax()),
258	                ast::AssocItem::TypeAlias(item) => {
259	                    (SymbolKind::TypeAlias, item.name(), item.visibility(), item.syntax())
260	                }

