use super::*;

#[test]
#[ignore]
fn probe() {
    let kind = std::env::var("KIND").unwrap();
    let depth: usize = std::env::var("DEPTH").unwrap().parse().unwrap();
    let stack: usize = std::env::var("STACK").unwrap().parse().unwrap();
    let stmt = std::env::var("STMT").is_ok();
    let rep = |a: &str, tail: &str, c: &str| {
        format!("pub fn deep() {{ let x = {}{}{}; }}\npub fn after() {{}}\n", a.repeat(depth), tail, c.repeat(depth))
    };
    let text = match kind.as_str() {
        "paren" => rep("(", "1", ")"),
        "array" => rep("[", "1", "]"),
        "block" => rep("{", "1", "}"),
        "closure" => rep("|a| ", "1", ""),
        "neg" => rep("- ", "1", ""),
        "not" => rep("!", "1", ""),
        "ref" => rep("&", "1", ""),
        "deref" => rep("*", "1", ""),
        "tuple" => rep("(1, ", "1", ")"),
        "call" => rep("f(", "1", ")"),
        "macro" => rep("m!(", "1", ")"),
        "ifelse" => rep("if a { 1 } else ", "{ 1 }", ""),
        "match" => rep("match a { _ => ", "1", "}"),
        "loop" => rep("loop { ", "1", "}"),
        "unsafe" => rep("unsafe { ", "1", "}"),
        "async" => rep("async { ", "1", "}"),
        "return" => rep("return ", "1", ""),
        "assign" => format!("pub fn deep() {{ {}1; }}\npub fn after() {{}}\n", "x = ".repeat(depth)),
        "binary" => format!("pub fn deep() {{ let x = 1{}; }}\npub fn after() {{}}\n", "+1".repeat(depth)),
        "method" => format!("pub fn deep() {{ let x = a{}; }}\npub fn after() {{}}\n", ".b()".repeat(depth)),
        "field" => format!("pub fn deep() {{ let x = a{}; }}\npub fn after() {{}}\n", ".b".repeat(depth)),
        "try" => format!("pub fn deep() {{ let x = a{}; }}\npub fn after() {{}}\n", "?".repeat(depth)),
        "as" => format!("pub fn deep() {{ let x = a{}; }}\npub fn after() {{}}\n", " as u8".repeat(depth)),
        "range" => rep("..", "1", ""),
        "gen" => format!("pub type T = {}u8{};\n", "A<".repeat(depth), ">".repeat(depth)),
        "tref" => format!("pub type T = {}u8;\n", "&".repeat(depth)),
        "ttuple" => format!("pub type T = {}u8{};\n", "(".repeat(depth), ",)".repeat(depth)),
        "tarr" => format!("pub type T = {}u8{};\n", "[".repeat(depth), ";1]".repeat(depth)),
        "tfn" => format!("pub type T = {}u8;\n", "fn() -> ".repeat(depth)),
        "mod" => format!("{}pub fn leaf() {{}}\n{}", "mod m { ".repeat(depth), "}".repeat(depth)),
        "fnitem" => format!("{}{}\n", "fn a() { ".repeat(depth), "}".repeat(depth)),
        "pat" => format!("fn a() {{ let {}x{} = 1; }}\n", "(".repeat(depth), ",)".repeat(depth)),
        "patref" => format!("fn a() {{ let {}x = 1; }}\n", "&".repeat(depth)),
        "patsome" => format!("fn a() {{ let {}x{} = 1; }}\n", "Some(".repeat(depth), ")".repeat(depth)),
        "attr" => format!("#[a{}]\nfn a() {{}}\n", "(b".repeat(depth) + &")".repeat(depth)),
        "impl" => format!("{}{}\n", "impl A { fn b() { ".repeat(depth), "} }".repeat(depth)),
        "label" => format!("fn a() {{ {}1{} }}\n", "'a: { ".repeat(depth), "}".repeat(depth)),
        "tt" => format!("m!{}{};\n", "(".repeat(depth), ")".repeat(depth)),
        _ => panic!("kind"),
    };
    let r = guarded(stack, || {
        let parse = SourceFile::parse(&text, Edition::CURRENT);
        let d = tree_depth(&parse.syntax_node());
        println!("tree_depth {d}");
        let out = if stmt {
            Extraction::default()
        } else {
            parse_and_extract_no_cap(Utf8Path::new("a.rs"), &text, AnalysisProfile::Full, parse)
        };
        out
    });
    println!("OK {} {:?} {}", r.symbols.len(), r.degradation, r.had_parse_errors);
}

fn parse_and_extract_no_cap(
    path: &Utf8Path,
    source: &str,
    profile: AnalysisProfile,
    parse: ra_ap_syntax::Parse<SourceFile>,
) -> Extraction {
    let had_parse_errors = !parse.errors().is_empty();
    let Some(file) = SourceFile::cast(parse.syntax_node()) else {
        return Extraction::degraded(Degradation::Panicked);
    };
    let mut walker = Walker { path, source, profile, lines: LineIndex::new(source), out: Extraction::default() };
    walker.items(file.items(), None, false);
    std::mem::forget(parse);
    Extraction { had_parse_errors, ..walker.out }
}

