        let parse = SourceFile::parse(&text, Edition::CURRENT);
        let d = tree_depth(&parse.syntax_node());
        println!("tree_depth {d}");
        let out = if stmt {
            Extraction::default()
        } else {
            parse_and_extract_no_cap(Utf8Path::new("a.rs"), &text, AnalysisProfile::Full, parse)
        };
        out
    });
    println!("OK {} {:?} {}", r.symbols.len(), r.degradation, r.had_parse_errors);
}

fn parse_and_extract_no_cap(
    path: &Utf8Path,
    source: &str,
    profile: AnalysisProfile,
    parse: ra_ap_syntax::Parse<SourceFile>,
) -> Extraction {
    let had_parse_errors = !parse.errors().is_empty();
    let Some(file) = SourceFile::cast(parse.syntax_node()) else {
        return Extraction::degraded(Degradation::Panicked);
    };
    let mut walker = Walker { path, source, profile, lines: LineIndex::new(source), out: Extraction::default() };
    walker.items(file.items(), None, false);
    std::mem::forget(parse);
    Extraction { had_parse_errors, ..walker.out }
}

