//! A bound on how deep a source file recurses, computed in one pass before any parser or tree walk sees it.
//!
//! The parsers and the extractors recurse once per nesting level, and a stack overflow aborts the process, so a file's
//! depth must be known to be small before it is parsed. [`peak_cost`] estimates the worst recursion the file could cause
//! as a number of units, in time and memory proportional to the source length and the limit.
//!
//! # What a unit is
//!
//! | Token | Cost |
//! | --- | --- |
//! | `(` `[` `{` and the `${` of a template | [`FRAME_COST`], and a frame the closer pops |
//! | a closer that pops a frame | 1 left behind, because `a()()()` and `a[0][0]` nest through the calls |
//! | `<` (generic arguments, JSX, a comparison) | the syntax's angle cost, which `,` does not reset |
//! | a word, a number, any other punctuation byte | 1 |
//!
//! The running cost of a frame is reset to the frame's start at `;`, and to what the frame's angle brackets added at `,`,
//! because nothing that recurses survives either. Without semicolons it is also reset when a word starts a new statement:
//! after a closing `}`, and after a line that ends in an operand when the next word cannot continue it. A string, a
//! comment, a regular expression and the text of a template cost nothing, since no recursion hangs on their content.
//!
//! # Never an underestimate
//!
//! An overestimate degrades a file that was not going to be useful. An underestimate lets a hostile file overflow the
//! parse stack and abort the process. So wherever the scan cannot tell what a byte is, it takes the reading that costs
//! more:
//!
//! - A closer that does not match the innermost open frame is ignored, and a frame is only ever popped by a closer of its
//!   own kind.
//! - A quote with no closing quote on its line is an operator, not a string.
//! - In a file that may hold JSX, text that looks like a string or a comment may be JSX text, which can hold an
//!   expression in braces and nested tags. Such text that contains a `{` is scanned as code, and one that contains `<`
//!   charges each of them.
//! - A `/` after an operand is a division, so what follows it is code. After a closing `}` it may start a regular
//!   expression instead, so the closers up to the next `/` on the line do not pop anything.
//!
//! Which of these a scan took is observable only in the returned number, so each has a test that a nest hidden behind
//! it is still counted.

use std::ops::Range;

/// What a frame costs: a nested bracket is the deepest recursion per byte either parser has, at 1.6 KB of stack per
/// level in a build without optimizations. Everything else is priced in this unit; see `PARSE_STACK_BYTES`.
pub(crate) const FRAME_COST: usize = 4;

/// Which language's lexical rules the scan follows.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Syntax {
    /// `jsx` is whether the file may hold JSX, whose text can look like strings and comments.
    #[cfg(feature = "lang-ts")]
    TypeScript { jsx: bool },
    #[cfg(feature = "lang-rust")]
    Rust,
}

impl Syntax {
    /// The cost of `<`: each level of generic arguments is five tree levels deep in Rust and about three frames' worth of
    /// stack in TypeScript, and a comma inside does not end it.
    const fn angle_cost(self) -> usize {
        match self {
            #[cfg(feature = "lang-ts")]
            Self::TypeScript { .. } => 2,
            #[cfg(feature = "lang-rust")]
            Self::Rust => 4,
        }
    }

    /// Whether the source may hold text that is neither code nor a string or comment: JSX text.
    const fn text_may_hide_code(self) -> bool {
        match self {
            #[cfg(feature = "lang-ts")]
            Self::TypeScript { jsx } => jsx,
            #[cfg(feature = "lang-rust")]
            Self::Rust => false,
        }
    }

    /// Whether a word right after a closing `}` on the same line starts a new statement. In JSX it can be the next
    /// attribute.
    const fn brace_ends_statement(self) -> bool {
        !self.text_may_hide_code()
    }

    /// Whether a line ending in an operand ends the statement when the next line starts with a word. Rust has semicolons.
    const fn newline_ends_statement(self) -> bool {
        match self {
            #[cfg(feature = "lang-ts")]
            Self::TypeScript { .. } => true,
            #[cfg(feature = "lang-rust")]
            Self::Rust => false,
        }
    }

    #[cfg(feature = "lang-rust")]
    const fn is_rust(self) -> bool {
        match self {
            #[cfg(feature = "lang-ts")]
            Self::TypeScript { .. } => false,
            Self::Rust => true,
        }
    }
}

/// The largest cost the source can reach, or the first cost over `limit` if it passes it, which ends the scan early so
/// the frame stack stays within `limit / FRAME_COST` entries.
pub(crate) fn peak_cost(source: &str, syntax: Syntax, limit: usize) -> usize {
    let mut scan = Scan::new(source.as_bytes(), syntax);
    while scan.i < scan.bytes.len() && scan.peak <= limit {
        scan.step();
    }
    scan.peak
}

/// A bracket that is open.
struct Frame {
    kind: u8,
    /// Where it opened.
    pos: usize,
    /// The enclosing frame's cost, base and keep, restored when this one closes.
    cost: usize,
    base: usize,
    keep: usize,
    /// The parenthesis of an `if`, `for`, `while` or `with`, whose closer does not end an operand: a statement follows.
    head: bool,
    /// The `${` of a template, whose closer resumes the template's text.
    template: bool,
}

/// Text scanned as code because it might be.
struct Region {
    start: usize,
    end: usize,
    close_len: usize,
    operand: bool,
    opens_template: bool,
}

struct Scan<'s> {
    bytes: &'s [u8],
    syntax: Syntax,
    i: usize,
    /// The recursion the position is inside, in units.
    cost: usize,
    /// What `cost` returns to at a `;`: the cost when the innermost frame opened.
    base: usize,
    /// What `cost` returns to at a `,`: `base` plus the angle brackets since.
    keep: usize,
    peak: usize,
    frames: Vec<Frame>,
    /// The last token ends an operand, so a `/` after it divides.
    operand: bool,
    /// The last token is the `}` of a brace frame.
    closed_brace: bool,
    /// The last token is `if`, `for`, `while` or `with`.
    head_next: bool,
    /// A line break came since the last token.
    newline: bool,
    plain: Option<Region>,
    /// Closers before this offset pop nothing.
    no_pop_until: usize,
}

impl<'s> Scan<'s> {
    fn new(bytes: &'s [u8], syntax: Syntax) -> Self {
        Self {
            bytes,
            syntax,
            i: 0,
            cost: 0,
            base: 0,
            keep: 0,
            peak: 0,
            frames: Vec::new(),
            operand: false,
            closed_brace: false,
            head_next: false,
            newline: false,
            plain: None,
            no_pop_until: 0,
        }
    }

    fn at(&self, index: usize) -> u8 {
        self.bytes.get(index).copied().unwrap_or(0)
    }

    fn bump(&mut self, cost: usize) {
        self.cost += cost;
        self.peak = self.peak.max(self.cost);
    }

    /// A cost that a `,` does not undo.
    fn bump_kept(&mut self, cost: usize) {
        self.bump(cost);
        self.keep += cost;
    }

    fn reset(&mut self) {
        self.cost = self.base;
        self.keep = self.base;
    }

    /// The state after any token but a bracket or a word.
    fn token(&mut self, operand: bool) {
        self.operand = operand;
        self.closed_brace = false;
        self.head_next = false;
        self.newline = false;
    }

    fn step(&mut self) {
        if let Some(region) = &self.plain
            && self.i >= region.end
        {
            self.end_plain();
            return;
        }
        let byte = self.at(self.i);
        match byte {
            b'\n' => {
                self.newline = true;
                self.i += 1;
            }
            b if b.is_ascii_whitespace() => self.i += 1,
            b if is_word_byte(b) => self.word(),
            b'\\' => {
                // Outside a string only an identifier's escape has one, and a bracket cannot follow it.
                self.i += if self.at(self.i + 1) == b'\r' && self.at(self.i + 2) == b'\n' { 3 } else { 2 };
            }
            b'(' | b'[' | b'{' => self.open(byte),
            b')' | b']' | b'}' => self.close(byte),
            b',' => {
                self.cost = self.keep;
                self.token(false);
                self.i += 1;
            }
            b';' => {
                self.reset();
                self.token(false);
                self.i += 1;
            }
            b'/' | b'\'' | b'"' | b'`' if self.plain.is_none() => self.quote_or_slash(byte),
            _ => self.punctuation(byte),
        }
    }

    fn punctuation(&mut self, byte: u8) {
        let previous = self.at(self.i.wrapping_sub(1));
        let mut operand = false;
        match byte {
            b'<' => self.bump_kept(self.syntax.angle_cost()),
            #[cfg(feature = "lang-rust")]
            b'|' if self.syntax.is_rust() => self.bump_kept(1),
            _ => self.bump(1),
        }
        match byte {
            // `a++` and `a--` end an operand, and `a!` does when it follows one.
            b'+' | b'-' => operand = previous == byte && self.i > 0,
            b'!' => operand = self.operand,
            _ => {}
        }
        self.token(operand);
        self.i += 1;
    }

    fn word(&mut self) {
        let start = self.i;
        let mut end = start;
        while is_word_byte(self.at(end)) && end < self.bytes.len() {
            end += 1;
        }
        let word = self.bytes.get(start..end).unwrap_or_default();
        #[cfg(feature = "lang-rust")]
        if self.syntax.is_rust()
            && matches!(word, b"r" | b"br" | b"cr")
            && let Some(content) = raw_string(self.bytes, end)
        {
            self.skip(content.start..content.end, end - start + content.start - end, true);
            return;
        }
        self.starts_operand(word);
        self.bump(1);
        self.token(!is_operator_word(word));
        self.head_next = matches!(word, b"if" | b"for" | b"while" | b"with");
        self.i = end;
    }

    /// A word or literal is about to start. After an operand that ends its statement it begins the next one, so nothing
    /// that came before it nests around it.
    fn starts_operand(&mut self, word: &[u8]) {
        if is_continuation_word(word) || !self.operand {
            return;
        }
        let same_line = self.closed_brace && self.syntax.brace_ends_statement();
        if same_line || (self.newline && self.syntax.newline_ends_statement()) {
            self.reset();
        }
    }

    fn open(&mut self, kind: u8) {
        let head = kind == b'(' && self.head_next;
        self.push(kind, head, false);
        self.i += 1;
        self.token(false);
    }

    fn push(&mut self, kind: u8, head: bool, template: bool) {
        self.frames.push(Frame {
            kind,
            pos: self.i,
            cost: self.cost,
            base: self.base,
            keep: self.keep,
            head,
            template,
        });
        self.bump(FRAME_COST);
        self.base = self.cost;
        self.keep = self.cost;
    }

    fn close(&mut self, byte: u8) {
        let kind = match byte {
            b')' => b'(',
            b']' => b'[',
            _ => b'{',
        };
        let floor = self.plain.as_ref().map_or(0, |region| region.start);
        let poppable = self.i >= self.no_pop_until
            && self.frames.last().is_some_and(|frame| frame.kind == kind && frame.pos >= floor);
        let Some(frame) = poppable.then(|| self.frames.pop()).flatten() else {
            self.bump(1);
            self.token(true);
            self.i += 1;
            return;
        };
        self.cost = frame.cost;
        self.base = frame.base;
        self.keep = frame.keep;
        self.bump(1);
        self.i += 1;
        if frame.template {
            self.template(self.i);
            return;
        }
        self.token(!frame.head);
        self.closed_brace = kind == b'{' && !frame.head;
    }

    fn quote_or_slash(&mut self, byte: u8) {
        match self.syntax {
            #[cfg(feature = "lang-ts")]
            Syntax::TypeScript { .. } => self.typescript_quote_or_slash(byte),
            #[cfg(feature = "lang-rust")]
            Syntax::Rust => self.rust_quote_or_slash(byte),
        }
    }

    /// Skips the text `content`, closed by `close_len` bytes, or scans it as code if it might be code. Text that cannot
    /// be code is free; text that might be is [`Syntax::text_may_hide_code`]'s JSX text.
    fn skip(&mut self, content: Range<usize>, close_len: usize, operand: bool) {
        self.skip_into(content, close_len, operand, false);
    }

    fn skip_into(&mut self, content: Range<usize>, close_len: usize, operand: bool, opens_template: bool) {
        let text = self.bytes.get(content.clone()).unwrap_or_default();
        if self.syntax.text_may_hide_code() {
            if text.contains(&b'{') {
                self.plain = Some(Region {
                    start: content.start,
                    end: content.end,
                    close_len,
                    operand,
                    opens_template,
                });
                self.i = content.start;
                return;
            }
            let angles = text.iter().filter(|&&byte| byte == b'<').count();
            self.bump_kept(angles);
        }
        if text.contains(&b'\n') {
            self.newline = true;
        }
        self.finish(content.end + close_len, operand, opens_template);
    }

    fn end_plain(&mut self) {
        if let Some(region) = self.plain.take() {
            self.finish(region.end + region.close_len, region.operand, region.opens_template);
        }
    }

    /// Resumes after skipped text.
    fn finish(&mut self, next: usize, operand: bool, opens_template: bool) {
        self.i = next;
        self.operand = operand;
        self.closed_brace = false;
        self.head_next = false;
        if opens_template {
            self.i = next.min(self.bytes.len());
            self.push(b'{', false, true);
            self.operand = false;
        }
    }

    /// The text of a template starting at `from`, up to its closing backtick or its next `${`.
    #[cfg(feature = "lang-ts")]
    fn template(&mut self, from: usize) {
        let mut end = from;
        loop {
            match self.at(end) {
                _ if end >= self.bytes.len() => return self.skip(from..self.bytes.len(), 0, true),
                b'\\' => end += 2,
                b'`' => return self.skip(from..end, 1, true),
                b'$' if self.at(end + 1) == b'{' => {
                    // The frame sits at the `{`, so a closer inside the text cannot pop it.
                    return self.skip_into(from..end, 1, false, true);
                }
                _ => end += 1,
            }
        }
    }

    #[cfg(feature = "lang-ts")]
    fn typescript_quote_or_slash(&mut self, byte: u8) {
        let start = self.i;
        match byte {
            b'`' => {
                self.starts_operand(b"`");
                self.template(start + 1);
            }
            b'/' => match self.at(start + 1) {
                b'/' => {
                    let end = self.bytes.get(start..).and_then(|rest| rest.iter().position(|&b| b == b'\n'));
                    let end = end.map_or(self.bytes.len(), |offset| start + offset);
                    self.skip(start + 2..end, 0, self.operand);
                }
                b'*' => {
                    let rest = self.bytes.get(start + 2..).unwrap_or_default();
                    match rest.windows(2).position(|pair| pair == b"*/") {
                        Some(offset) => self.skip(start + 2..start + 2 + offset, 2, self.operand),
                        None => self.skip(start + 2..self.bytes.len(), 0, self.operand),
                    }
                }
                _ => self.slash(),
            },
            _ => {
                let end = self.string_end(start, byte);
                match end {
                    Some(end) => {
                        self.starts_operand(b"\"");
                        self.skip(start + 1..end, 1, true);
                    }
                    None => self.punctuation(byte),
                }
            }
        }
    }

    /// Where the string opened by the quote at `start` closes on its line, if it does.
    #[cfg(feature = "lang-ts")]
    fn string_end(&self, start: usize, quote: u8) -> Option<usize> {
        let mut index = start + 1;
        while index < self.bytes.len() {
            match self.at(index) {
                b'\\' => index += if self.at(index + 1) == b'\r' && self.at(index + 2) == b'\n' { 3 } else { 2 },
                b'\n' | b'\r' => return None,
                byte if byte == quote => return Some(index),
                _ => index += 1,
            }
        }
        None
    }

    /// A `/` that is not a comment: a division after an operand, a regular expression otherwise.
    #[cfg(feature = "lang-ts")]
    fn slash(&mut self) {
        let start = self.i;
        let after_angle = start > 0 && self.at(start - 1) == b'<';
        if after_angle || (self.operand && !self.closed_brace) {
            self.punctuation(b'/');
            return;
        }
        let Some(end) = self.regex_end(start) else {
            self.punctuation(b'/');
            return;
        };
        if self.operand {
            // After a `}` the `/` is a division of an object or the start of a regex after a block. As a regex it hides
            // closers, so none of them up to its end may pop a frame.
            self.no_pop_until = end + 1;
            self.punctuation(b'/');
            return;
        }
        self.skip(start + 1..end, 1, true);
    }

    #[cfg(feature = "lang-ts")]
    fn regex_end(&self, start: usize) -> Option<usize> {
        let mut index = start + 1;
        let mut class = false;
        while index < self.bytes.len() {
            match self.at(index) {
                b'\\' => index += 1,
                b'\n' | b'\r' => return None,
                b'[' => class = true,
                b']' => class = false,
                b'/' if !class => return Some(index),
                _ => {}
            }
            index += 1;
        }
        None
    }

    #[cfg(feature = "lang-rust")]
    fn rust_quote_or_slash(&mut self, byte: u8) {
        let start = self.i;
        match byte {
            b'/' => match self.at(start + 1) {
                b'/' => {
                    let end = self.bytes.get(start..).and_then(|rest| rest.iter().position(|&b| b == b'\n'));
                    let end = end.map_or(self.bytes.len(), |offset| start + offset);
                    self.skip(start + 2..end, 0, self.operand);
                }
                b'*' => {
                    let (end, close_len) = rust_block_comment_end(self.bytes, start + 2);
                    self.skip(start + 2..end, close_len, self.operand);
                }
                _ => self.punctuation(byte),
            },
            b'"' => {
                let mut index = start + 1;
                while index < self.bytes.len() && self.at(index) != b'"' {
                    index += if self.at(index) == b'\\' { 2 } else { 1 };
                }
                let end = index.min(self.bytes.len());
                self.starts_operand(b"\"");
                self.skip(start + 1..end, usize::from(end < self.bytes.len()), true);
            }
            b'\'' => match self.char_literal_len(start) {
                Some(len) => {
                    self.starts_operand(b"'");
                    self.skip(start + 1..start + len - 1, 1, true);
                }
                None => self.punctuation(byte),
            },
            _ => self.punctuation(byte),
        }
    }

    /// The length of the character literal that starts at `start`, quotes included, or `None` for a lifetime or label.
    #[cfg(feature = "lang-rust")]
    fn char_literal_len(&self, start: usize) -> Option<usize> {
        let first = self.at(start + 1);
        if first == b'\\' {
            // The longest escape is `\u{10FFFF}`.
            return (start + 3..start + 13).find(|&index| self.at(index) == b'\'').map(|index| index - start + 1);
        }
        let width = match first {
            0..=0x7f => 1,
            0xc0..=0xdf => 2,
            0xe0..=0xef => 3,
            _ => 4,
        };
        (self.at(start + 1 + width) == b'\'').then_some(width + 2)
    }
}

fn is_word_byte(byte: u8) -> bool {
    byte.is_ascii_alphanumeric() || matches!(byte, b'_' | b'$') || byte >= 0x80
}

/// Words after which an expression starts, so a `/` begins a regular expression and no operand has ended.
fn is_operator_word(word: &[u8]) -> bool {
    matches!(
        word,
        b"as"
            | b"asserts"
            | b"await"
            | b"case"
            | b"delete"
            | b"do"
            | b"else"
            | b"extends"
            | b"implements"
            | b"in"
            | b"infer"
            | b"instanceof"
            | b"is"
            | b"keyof"
            | b"new"
            | b"of"
            | b"readonly"
            | b"return"
            | b"satisfies"
            | b"throw"
            | b"typeof"
            | b"unique"
            | b"void"
            | b"yield"
    )
}

/// Words that continue the statement before them even on a new line.
fn is_continuation_word(word: &[u8]) -> bool {
    matches!(
        word,
        b"as"
            | b"catch"
            | b"else"
            | b"extends"
            | b"finally"
            | b"implements"
            | b"in"
            | b"instanceof"
            | b"is"
            | b"of"
            | b"satisfies"
            | b"where"
            | b"while"
    )
}

/// The content of the raw string whose `#`s and opening quote start at `from`, if one does. A raw string ends at a quote
/// followed by as many `#`s as it opened with, or at the end of the source.
#[cfg(feature = "lang-rust")]
fn raw_string(bytes: &[u8], from: usize) -> Option<Range<usize>> {
    let hashes = bytes.get(from..)?.iter().take_while(|&&byte| byte == b'#').count();
    if bytes.get(from + hashes) != Some(&b'"') {
        return None;
    }
    let content = from + hashes + 1;
    let closing: Vec<u8> = std::iter::once(b'"').chain(std::iter::repeat_n(b'#', hashes)).collect();
    let rest = bytes.get(content..)?;
    let end = rest.windows(closing.len()).position(|window| window == closing).map_or(bytes.len(), |at| content + at);
    Some(content..end)
}

/// Where the block comment whose text starts at `from` ends, and how long its closer is. Rust's nest.
#[cfg(feature = "lang-rust")]
fn rust_block_comment_end(bytes: &[u8], from: usize) -> (usize, usize) {
    let (mut depth, mut index) = (1usize, from);
    while index < bytes.len() {
        match bytes.get(index..index + 2) {
            Some(b"/*") => {
                depth += 1;
                index += 2;
            }
            Some(b"*/") => {
                depth -= 1;
                if depth == 0 {
                    return (index, 2);
                }
                index += 2;
            }
            _ => index += 1,
        }
    }
    (bytes.len(), 0)
}

