    let previous = self.at(self.i.wrapping_sub(1));
    let mut operand = false;
    match byte {
        b'<' => self.bump_kept(self.syntax.angle_cost()),
        #[cfg(feature = "lang-rust")]
        b'|' if self.syntax.is_rust() => self.bump_kept(1),
        _ => self.bump(1),
    }
