        self.skip(content, close_len, true);
        return;
    }
    self.starts_operand(word);
    self.bump(1);
    self.token(!is_operator_word(word));
    if matches!(word, b"if" | b"for" | b"while" | b"with") {
        self.last = Last::HeadWord;
    }
    self.i = end;
