/// be code is free; text that might be is [`Syntax::text_may_hide_code`]'s JSX text.
fn skip(&mut self, content: Range<usize>, close_len: usize, operand: bool) {
    self.skip_into(content, close_len, operand, false);
}

fn skip_into(&mut self, content: Range<usize>, close_len: usize, operand: bool, opens_template: bool) {
    let text = self.bytes.get(content.clone()).unwrap_or_default();
    if self.syntax.text_may_hide_code() {
        if text.contains(&b'{') {
            self.plain =
                Some(Region { start: content.start, end: content.end, close_len, operand, opens_template });
            self.i = content.start;
            return;
        }
